const W=eval(load("wttjHelpers"));
async function round(){
await W.nav("tab_j","https://www.welcometothejungle.com/fr/jobs-matches");await W.delay(300);
const cards=await W.ev("tab_j","[...new Map([...document.querySelectorAll('a[href*=\"/jobs/\"]')].filter(x=>x.innerText).map(x=>[x.href,{href:x.href,text:x.innerText,card:x.closest('article')?.innerText||x.parentElement.parentElement.innerText}])).values()]");
const region=load("wttjSearchLocation")||"Paris";const key="wttjRegion-"+region;store(key,[...new Map([...(load(key)||[]),...cards].map(x=>[x.href,x])).values()]);
let count=0;const seen=new Set(load("wttjSeen"));
for(const c of cards){if(seen.has(c.href))continue;count++;
if(!/software|full.?stack|front.?end|back.?end|développeur|développeuse|developer|founding.*engineer|product.*engineer|staff engineer|principal engineer|AI.*Engineer|engineer.*AI|machine learning|tech lead|CTO|DevOps|SRE|site reliability|ingénieur.*(?:logiciel|cloud|sécurité)/i.test(c.text)||/designer|quality|qualité produit|product assurance|electroni|électroni|radio.altim/i.test(c.text)){await W.nav("tab_j",c.href);await W.blocked(c,"Outside software-engineering scope");}
else if(/analytics|data engineer|ingénieur.*données|product manager|chef.*produit|radio.altim|electronique|électronique|bess|ligne de produit/i.test(c.text)){await W.nav("tab_j",c.href);await W.blocked(c,"Deferred: SWE and founding-engineer priority, or non-software role");}
else if(/(?:\b[123]\d|\b4[0-4])K\s*à/.test(c.card)||/Business Develop|Développeur Commercial|Directeur Commercial|Account Manager|Account Developer|Talent Acquisition|^Sales |Windev|WebDev|Vehicle Motion|Algorithmes des Systèmes|C\/ADA|Optimisation|quantique|Mechanical|mécanique/i.test(c.text)){await W.nav("tab_j",c.href);await W.blocked(c,"Outside fit or advertised salary begins below 45k");}
else{const r=await W.basic(c);if(r?.needsReview){let v=load("wttjReviews")||[];v.push({card:c,form:r.form});store("wttjReviews",v);text({review:c.text,company:c.card.split("\n\n")[1]});}}
seen.add(c.href);store("wttjSeen",Array.from(seen));
}
await W.H.saveJSON("job-search/wttj-"+region.toLowerCase().replace(/ /g,"-")+"-queue.json",load(key));await W.H.saveJSON("job-search/wttj-review-queue.json",load("wttjReviews"));await W.H.saveJSON("job-search/wttj-attempted-urls.json",load("wttjSeen"));return {processed:count,totalCollected:load(key).length};
}
({round,W})
